    #[test]
    fn auth_session_preserves_saved_choices_and_explicit_overrides() {
        let temp = tempfile::tempdir().unwrap();
        let mut install = Installation::at_home(temp.path().to_path_buf(), None);
        assert_eq!(install.selected_auth_session().unwrap(), AuthSession::Login);
        fs::create_dir_all(&install.root).unwrap();
        let metadata = install.root.join("installation.json");
        for session in [AuthSession::Login, AuthSession::Isolated] {
            fs::write(&metadata, json!({"authSession":session}).to_string()).unwrap();
            // The saved choice also survives removal of the service plist.
            assert_eq!(install.selected_auth_session().unwrap(), session);
        }
        install.auth_session = Some(AuthSession::Login);
        assert_eq!(install.selected_auth_session().unwrap(), AuthSession::Login);
        fs::write(&metadata, r#"{"authSession":"unknown"}"#).unwrap();
        // An explicit selection can repair an invalid stored choice.
        assert_eq!(install.selected_auth_session().unwrap(), AuthSession::Login);
        install.auth_session = None;
        assert!(install.selected_auth_session().is_err());
    }

    #[tokio::test]
    async fn installed_auth_session_survives_readiness_failure() {
        let temp = tempfile::tempdir().unwrap();
        let mut install = Installation::at_home(temp.path().to_path_buf(), None);
        fs::create_dir_all(&install.root).unwrap();
        let metadata = install.root.join("installation.json");
        fs::write(&metadata, r#"{"authSession":"isolated","version":"kept"}"#).unwrap();
        // The replacement definition was accepted by launchd, but its socket
        // never appears. A later reinstall must retain the applied choice.
        install.auth_session = Some(AuthSession::Login);
        fs::create_dir_all(install.plist.parent().unwrap()).unwrap();
        fs::write(&install.plist, install.render_plist().unwrap()).unwrap();
        let error = install
            .finish_service_install(AuthSession::Login)
            .await
            .unwrap_err();
        assert!(error.to_string().contains("Service not ready"));
        let metadata: Value = serde_json::from_slice(&fs::read(metadata).unwrap()).unwrap();
        assert_eq!(metadata["authSession"], "login");
        assert_eq!(metadata["version"], "kept");
        let next = Installation::at_home(temp.path().to_path_buf(), None);
        assert_eq!(next.selected_auth_session().unwrap(), AuthSession::Login);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn auth_session_migrates_the_existing_owned_service_definition() {
        let temp = tempfile::tempdir().unwrap();
        let install = Installation::at_home(temp.path().to_path_buf(), None);
        fs::create_dir_all(install.plist.parent().unwrap()).unwrap();
        let default_plist = install.render_plist().unwrap();
        for (key, expected) in [
            ("", AuthSession::Login),
            ("<key>SessionCreate</key>\n  <false/>", AuthSession::Login),
            ("<key>SessionCreate</key>\n  <true/>", AuthSession::Isolated),
        ] {
            let plist = default_plist.replace("</dict></plist>", &format!("{key}</dict></plist>"));
            fs::write(&install.plist, plist).unwrap();
            assert_eq!(install.selected_auth_session().unwrap(), expected);
            // Re-rendering and a subsequent installer retain the migrated mode.
            fs::write(&install.plist, install.render_plist().unwrap()).unwrap();
            let next = Installation::at_home(temp.path().to_path_buf(), None);
            assert_eq!(next.selected_auth_session().unwrap(), expected);
        }
        fs::create_dir_all(&install.root).unwrap();
        fs::write(
            install.root.join("installation.json"),
            r#"{"authSession":"login"}"#,
        )
        .unwrap();
        let isolated_plist = default_plist.replace(
            "</dict></plist>",
            "<key>SessionCreate</key><true/></dict></plist>",
        );
        fs::write(&install.plist, isolated_plist).unwrap();
        assert_eq!(install.selected_auth_session().unwrap(), AuthSession::Login);
        fs::remove_file(install.root.join("installation.json")).unwrap();
        let invalid = default_plist.replace(
            "</dict></plist>",
            "<key>SessionCreate</key><string>true</string></dict></plist>",
        );
        fs::write(&install.plist, invalid).unwrap();
        assert!(install.selected_auth_session().is_err());
        fs::write(&install.plist, "unrelated service").unwrap();
        assert!(install.selected_auth_session().is_err());
    }

    #[test]
    fn remote_shell_block_preserves_user_content_and_uninstalls_cleanly() {
        let install = Installation::at_home(PathBuf::from("/Users/example"), None);
        let original = "# Personal environment\nexport EXAMPLE=1\n";
        let block = install.remote_environment().unwrap();
        let updated = replace_remote_block(original, Some(&block)).unwrap();
        assert_eq!(
            replace_remote_block(&updated, Some(&block)).unwrap(),
            updated
        );
        assert_eq!(replace_remote_block(&updated, None).unwrap(), original);
        assert!(replace_remote_block("# BEGIN claudex remote desktop\n", Some(&block)).is_err());
        assert!(replace_remote_block("# END claudex remote desktop\n", None).is_err());
        assert!(replace_remote_block(&format!("{block}{block}"), Some(&block)).is_err());
    }

    #[test]
    fn remote_environment_routes_only_desktop_ssh_without_overriding_custom_connections() {
        let temp = tempfile::tempdir().unwrap();
        let install = Installation::at_home(temp.path().join("space 'quoted'"), None);
        let script = format!(
            "{}printf '%s\\n' \"${{CODEX_INSTALL_DIR:-}}\" \"${{CODEX_SSH_SKIP_APP_SERVER_BOOT:-}}\" \"$CODEX_HOME\"",
            install.remote_environment().unwrap()
        );
        for (ssh, payload, custom, expected) in [
            (false, false, None, "".to_owned()),
            (true, false, None, "".to_owned()),
            (false, true, None, "".to_owned()),
            (
                true,
                true,
                None,
                install.root.join("router").to_str().unwrap().to_owned(),
            ),
            (
                true,
                true,
                Some("/existing/connection"),
                "/existing/connection".to_owned(),
            ),
        ] {
            let mut command = std::process::Command::new("/bin/sh");
            command
                .args(["-c", &script])
                .env_remove("SSH_CONNECTION")
                .env_remove("CODEX_REMOTE_PAYLOAD")
                .env_remove("CODEX_INSTALL_DIR")
                .env_remove("CODEX_SSH_SKIP_APP_SERVER_BOOT")
                .env("CODEX_HOME", "/existing/codex-home");
            if ssh {
                command.env("SSH_CONNECTION", "client 123 host 22");
            }
            if payload {
                command.env("CODEX_REMOTE_PAYLOAD", "exec codex app-server proxy");
            }
            if let Some(custom) = custom {
                command.env("CODEX_INSTALL_DIR", custom);
            }
            let output = command.output().unwrap();
            assert!(output.status.success());
            let output = String::from_utf8(output.stdout).unwrap();
            let lines: Vec<_> = output.lines().collect();
            assert_eq!(lines[0], expected);
            assert_eq!(
                lines[1],
                if ssh && payload && custom.is_none() {
                    "true"
                } else {
                    ""
                }
            );
            assert_eq!(lines[2], "/existing/codex-home");
        }
    }

    #[test]
    fn ssh_install_is_idempotent_and_uninstall_preserves_other_hosts() {
        let install = Installation::at_home(PathBuf::from("/Users/example"), None);
        let original = "# Personal configuration\nHost work\n  HostName example.org\n";
        let block = install.ssh_config("example").unwrap();
        let installed = replace_ssh_block(original, Some(&block), &install).unwrap();
        assert_eq!(
            replace_ssh_block(&installed, Some(&block), &install).unwrap(),
            installed
        );
        assert_eq!(
            replace_ssh_block(&installed, None, &install).unwrap(),
            original
        );
        assert!(
            replace_ssh_block(
                "Host claude-codex-local\n HostName elsewhere\n",
                Some(&block),
                &install
            )
            .is_err()
        );
        assert!(replace_ssh_block(&install.begin, Some(&block), &install).is_err());
        assert!(replace_ssh_block(&install.end, Some(&block), &install).is_err());
    }

    #[test]
    fn ssh_authorization_keeps_existing_keys_and_refuses_weaker_duplicates() {
        let install = Installation::at_home(PathBuf::from("/Users/example"), None);
        let public = "ssh-ed25519 TEST_PUBLIC_KEY fixture\n";
        let line = install.authorized_line(public).unwrap();
        let original = "ssh-ed25519 OTHER_PUBLIC_KEY user";
        let installed = add_authorized_key(original, &line, public).unwrap();
        assert!(installed.starts_with(original));
        assert_eq!(
            add_authorized_key(&installed, &line, public).unwrap(),
            installed
        );
        assert!(add_authorized_key(public, &line, public).is_err());
        assert!(
            install
                .authorized_line("ssh-ed25519 KEY\nssh-ed25519 EXTRA")
                .is_err()
        );
    }

    #[test]
    fn file_updates_preserve_dotfiles_symlinks_and_permissions() {
        let temp = tempfile::tempdir().unwrap();
        let target = temp.path().join("dotfiles-config");
        let link = temp.path().join("config");
        fs::write(&target, "old").unwrap();
        fs::set_permissions(&target, fs::Permissions::from_mode(0o640)).unwrap();
        symlink(&target, &link).unwrap();
        write_user_file(&link, b"updated").unwrap();
        assert!(link.symlink_metadata().unwrap().file_type().is_symlink());
        assert_eq!(fs::read_to_string(target).unwrap(), "updated");
        assert_eq!(
            fs::metadata(link).unwrap().permissions().mode() & 0o777,
            0o640
        );
        let new = temp.path().join("private");
        write_user_file(&new, b"private").unwrap();
        assert_eq!(
            fs::metadata(new).unwrap().permissions().mode() & 0o777,
            0o600
        );
    }

